import { db } from "@/lib/db";
import { PageHeader, Panel } from "@/components/admin/ui";
import { CategoryForm, DeleteCategoryButton } from "@/components/admin/SmallForms";

export default async function AdminCategories() {
  const cats = await db.category.findMany({ orderBy: [{ sortOrder: "asc" }, { name: "asc" }], include: { _count: { select: { products: true } } } });
  const top = cats.filter((c) => !c.parentId);
  return (
    <>
      <PageHeader title="Categories" description="Top-level categories appear in the store menu; sub-categories appear as chips on the category page." />
      <Panel title="Add category" className="mb-6"><CategoryForm parents={top} /></Panel>
      <div className="space-y-4">
        {top.map((c) => (
          <Panel key={c.id}>
            <div className="mb-2 flex justify-between text-xs text-muted"><span>/category/{c.slug} · {c._count.products} products</span><DeleteCategoryButton id={c.id} /></div>
            <CategoryForm parents={top} initial={c} />
            <div className="mt-4 space-y-3 border-l-2 border-line pl-4">
              {cats.filter((s) => s.parentId === c.id).map((s) => (
                <div key={s.id}>
                  <div className="mb-1 flex justify-between text-xs text-muted"><span>/category/{s.slug} · {s._count.products} products</span><DeleteCategoryButton id={s.id} /></div>
                  <CategoryForm parents={top} initial={s} />
                </div>
              ))}
            </div>
          </Panel>
        ))}
      </div>
    </>
  );
}
